export const localizedPages = [
  ...es.map((page) => ({ ...page, lang: 'es', path: page.slug ? `es/${page.slug}` : 'es' })),
  ...pt.map((page) => ({ ...page, lang: 'pt', path: page.slug ? `pt/${page.slug}` : 'pt' })),
];

// English path -> { es, pt } localized paths, for hreflang alternates.
export const alternatesByEnglish = localizedPages.reduce((map, page) => {
  if (page.en === null || page.en === undefined) return map;
  (map[page.en] ||= {})[page.lang] = page.path;
  return map;
}, {});
